// Block definitions and procedural texture-atlas generation.
// Each block can have distinct top / side / bottom textures.

// (THREE is provided globally by the engine bridge in index.html.)

// Block IDs. 0 is always AIR.
const BLOCK = {
  AIR: 0,
  GRASS: 1,
  DIRT: 2,
  STONE: 3,
  SAND: 4,
  WOOD: 5,
  LEAVES: 6,
  PLANK: 7,
  WATER: 8,
  BEDROCK: 9,
  GLASS: 10,
  BRICK: 11,
  COBBLE: 12,
  SNOW: 13,
};

// Each tile is generated by a painter function onto a 16x16 canvas.
// Tiles are referenced by name; blocks map faces -> tile name.
const TILE = {};
let tileOrder = [];

function paint(name, fn) {
  TILE[name] = fn;
  tileOrder.push(name);
}

// Helper: fill base + speckle noise for a natural look.
function speckle(ctx, base, spots, seed = 1) {
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, 16, 16);
  let r = seed * 9301 + 49297;
  const rnd = () => { r = (r * 9301 + 49297) % 233280; return r / 233280; };
  for (const [color, amount] of spots) {
    ctx.fillStyle = color;
    for (let i = 0; i < amount; i++) {
      ctx.fillRect((rnd() * 16) | 0, (rnd() * 16) | 0, 1, 1);
    }
  }
}

paint('grass_top', (c) => speckle(c, '#5fa83d', [['#6fbf48', 60], ['#4e8f33', 50], ['#75c850', 30]], 3));
paint('grass_side', (c) => {
  speckle(c, '#7a5a3a', [['#6b4d30', 50], ['#8a6a44', 40]], 5);
  // green top strip
  c.fillStyle = '#5fa83d'; c.fillRect(0, 0, 16, 4);
  c.fillStyle = '#4e8f33';
  for (let x = 0; x < 16; x += 2) c.fillRect(x, 3 + ((x * 7) % 2), 1, 2);
});
paint('dirt', (c) => speckle(c, '#7a5a3a', [['#6b4d30', 60], ['#8a6a44', 45], ['#5e4329', 25]], 7));
paint('stone', (c) => speckle(c, '#888888', [['#777777', 70], ['#999999', 50], ['#6f6f6f', 25]], 11));
paint('cobble', (c) => {
  speckle(c, '#7c7c7c', [['#6a6a6a', 40], ['#909090', 30]], 13);
  c.strokeStyle = '#5c5c5c'; c.lineWidth = 1;
  c.strokeRect(0.5, 0.5, 7, 7); c.strokeRect(8.5, 4.5, 6, 6);
  c.strokeRect(2.5, 9.5, 6, 5);
});
paint('sand', (c) => speckle(c, '#dcd29a', [['#d0c587', 60], ['#e8dfaf', 40]], 17));
paint('wood_top', (c) => {
  speckle(c, '#b9925b', [['#a87f49', 30]], 19);
  c.strokeStyle = '#8a6a3f'; c.lineWidth = 1;
  for (let r = 6; r > 0; r -= 2) { c.beginPath(); c.arc(8, 8, r, 0, 7); c.stroke(); }
});
paint('wood_side', (c) => {
  speckle(c, '#6b4f2f', [['#5c4327', 40], ['#7c5d39', 40]], 23);
  c.fillStyle = '#4f3a22';
  for (let x = 2; x < 16; x += 5) c.fillRect(x, 0, 1, 16);
});
paint('leaves', (c) => {
  speckle(c, '#3f8f33', [['#357a2b', 90], ['#4aa53c', 70], ['#2c6624', 40]], 29);
});
paint('plank', (c) => {
  speckle(c, '#b08a52', [['#9e7b46', 40]], 31);
  c.fillStyle = '#8a6a3f';
  for (let y = 0; y < 16; y += 4) c.fillRect(0, y, 16, 1);
  c.fillRect(7, 0, 1, 4); c.fillRect(11, 4, 1, 4); c.fillRect(4, 8, 1, 4); c.fillRect(9, 12, 1, 4);
});
paint('water', (c) => {
  speckle(c, '#2b6fd6', [['#2461c4', 50], ['#3a80e8', 40]], 37);
});
paint('bedrock', (c) => speckle(c, '#3a3a3a', [['#2a2a2a', 70], ['#4a4a4a', 50], ['#1f1f1f', 30]], 41));
paint('glass', (c) => {
  c.clearRect(0, 0, 16, 16);
  c.fillStyle = 'rgba(180,220,235,0.25)'; c.fillRect(0, 0, 16, 16);
  c.strokeStyle = 'rgba(210,235,245,0.9)'; c.lineWidth = 1.5;
  c.strokeRect(1, 1, 14, 14);
  c.beginPath(); c.moveTo(3, 3); c.lineTo(7, 7); c.stroke();
});
paint('brick', (c) => {
  speckle(c, '#a44a3a', [['#933f30', 30]], 43);
  c.fillStyle = '#d8d2c4';
  for (let y = 0; y < 16; y += 4) c.fillRect(0, y, 16, 1);
  for (let y = 0; y < 16; y += 8) { c.fillRect(8, y, 1, 4); }
  for (let y = 4; y < 16; y += 8) { c.fillRect(4, y, 1, 4); c.fillRect(12, y, 1, 4); }
});
paint('snow', (c) => speckle(c, '#f2f7fb', [['#e4ecf3', 40], ['#ffffff', 40]], 47));

// Block -> face tiles. faces: [top, side, bottom] or single name.
const FACES = {
  [BLOCK.GRASS]: ['grass_top', 'grass_side', 'dirt'],
  [BLOCK.DIRT]: 'dirt',
  [BLOCK.STONE]: 'stone',
  [BLOCK.COBBLE]: 'cobble',
  [BLOCK.SAND]: 'sand',
  [BLOCK.WOOD]: ['wood_top', 'wood_side', 'wood_top'],
  [BLOCK.LEAVES]: 'leaves',
  [BLOCK.PLANK]: 'plank',
  [BLOCK.WATER]: 'water',
  [BLOCK.BEDROCK]: 'bedrock',
  [BLOCK.GLASS]: 'glass',
  [BLOCK.BRICK]: 'brick',
  [BLOCK.SNOW]: 'snow',
};

// Block metadata used by gameplay / rendering.
const BLOCK_INFO = {
  [BLOCK.GRASS]:  { name: 'Grass',   solid: true,  color: '#5fa83d' },
  [BLOCK.DIRT]:   { name: 'Dirt',    solid: true,  color: '#7a5a3a' },
  [BLOCK.STONE]:  { name: 'Stone',   solid: true,  color: '#888888' },
  [BLOCK.COBBLE]: { name: 'Cobblestone', solid: true, color: '#7c7c7c' },
  [BLOCK.SAND]:   { name: 'Sand',    solid: true,  color: '#dcd29a' },
  [BLOCK.WOOD]:   { name: 'Wood',    solid: true,  color: '#6b4f2f' },
  [BLOCK.LEAVES]: { name: 'Leaves',  solid: true,  color: '#3f8f33', transparent: true },
  [BLOCK.PLANK]:  { name: 'Planks',  solid: true,  color: '#b08a52' },
  [BLOCK.WATER]:  { name: 'Water',   solid: false, color: '#2b6fd6', transparent: true, liquid: true },
  [BLOCK.BEDROCK]:{ name: 'Bedrock', solid: true,  color: '#3a3a3a', unbreakable: true },
  [BLOCK.GLASS]:  { name: 'Glass',   solid: true,  color: '#bfe0ec', transparent: true },
  [BLOCK.BRICK]:  { name: 'Bricks',  solid: true,  color: '#a44a3a' },
  [BLOCK.SNOW]:   { name: 'Snow',    solid: true,  color: '#f2f7fb' },
};

// Blocks offered to the player in the build palette.
const PALETTE = [
  BLOCK.GRASS, BLOCK.DIRT, BLOCK.STONE, BLOCK.COBBLE, BLOCK.SAND,
  BLOCK.WOOD, BLOCK.PLANK, BLOCK.LEAVES, BLOCK.GLASS, BLOCK.BRICK, BLOCK.SNOW,
];

// Build atlas texture and a lookup of UV rects per tile.
let _atlas = null;
let _tileUV = null;

function buildAtlas() {
  if (_atlas) return { texture: _atlas, tileUV: _tileUV };
  const TS = 16;                       // tile size in px
  const cols = Math.ceil(Math.sqrt(tileOrder.length));
  const rows = Math.ceil(tileOrder.length / cols);
  const canvas = document.createElement('canvas');
  canvas.width = cols * TS;
  canvas.height = rows * TS;
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;

  _tileUV = {};
  tileOrder.forEach((name, i) => {
    const cx = (i % cols) * TS;
    const cy = ((i / cols) | 0) * TS;
    const tc = document.createElement('canvas');
    tc.width = TS; tc.height = TS;
    const tctx = tc.getContext('2d');
    tctx.imageSmoothingEnabled = false;
    TILE[name](tctx);
    ctx.drawImage(tc, cx, cy);
    // UV rect (flip Y for WebGL). Half-texel inset avoids edge bleeding.
    const pad = 0.05;
    const u0 = (cx + pad) / canvas.width;
    const v0 = 1 - (cy + TS - pad) / canvas.height;
    const u1 = (cx + TS - pad) / canvas.width;
    const v1 = 1 - (cy + pad) / canvas.height;
    _tileUV[name] = [u0, v0, u1, v1];
  });

  const tex = new THREE.CanvasTexture(canvas);
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  tex.generateMipmaps = false;
  tex.colorSpace = THREE.SRGBColorSpace;
  _atlas = tex;
  return { texture: _atlas, tileUV: _tileUV };
}

// Returns UV rect for a given block face direction.
// dir: 'top' | 'bottom' | 'side'
function faceUV(blockId, dir) {
  const f = FACES[blockId];
  let tile;
  if (Array.isArray(f)) tile = dir === 'top' ? f[0] : dir === 'bottom' ? f[2] : f[1];
  else tile = f;
  return _tileUV[tile];
}
